One assumption: the repo has a runner, `bin/triage-eval`, that runs one config on one ticket, loads the ticket itself, and prints the labels, reply, and usage as JSON. The script also assumes the `grade.py` flags shown in it. Change both if they differ.

**Gates before launch.** First I check that spe/predictions/r04.yaml and spe/plans/r04.md have not changed since their commit (`git diff --quiet HEAD -- spe/predictions/r04.yaml spe/plans/r04.md`). Next I run the grader selftest. The oracle labels taken from spe/evals/tasks/answers.json must score 100%. An empty labels file and a shuffled wrong file must both fail. I also check that answers.json holds exactly the 50 ticket IDs T001 to T050, because the set had 40 tickets before this round. I give judge.md one known good reply and one known rude reply and check that it scores them apart. Then I regrade round 3's saved labels with the round 4 grade.py as a control. If any round 3 score moves, that is a grader change. I log it in spe/failures.md before I go on. Then I do a dry run with `{ only: ['B:T001', 'C2:T001', 'C2:T002'], trials: 1 }`. Every phase must return valid output, and the leak scan must stay clean. If any gate fails, I stop and report. If all pass, I save the script as spe/evals/harness/r04-workflow.js and commit it locally without pushing. Then I launch the full run with `cap_usd` set to 40 minus what the dry run spent.

```js
export const meta = {
  name: 'triage-spe-r04',
  description: 'SPE round 4 for triage. Configs B and C2 on 50 tickets, 5 trials per cell. Code grader for category and priority, Opus judge for reply tone, $40 spend cap.',
  phases: [
    { title: 'Trials' },
    { title: 'Grade' },
    { title: 'Judge' },
    { title: 'Top-up' },
    { title: 'Synthesis' },
  ],
};

// ---------------- Arguments ----------------
// The runner pins the model under test (Sonnet 5.5) inside each config.
// The agent() model below is the driver that runs the runner. It is not the system under test.
const A = typeof args === 'object' && args ? args : {};
const ROUND = A.round ?? 4;
const RR = `r${String(ROUND).padStart(2, '0')}`;
const NEXT_ROUND = ROUND + 1;

const CONFIGS = A.configs ?? [
  { id: 'B', desc: '12-line prompt, 6 tools' },
  { id: 'C2', desc: '12-line prompt, 3 merged tools plus a separate check_status tool' },
];
const TICKETS = A.tickets ?? Array.from({ length: 50 }, (_, i) => `T${String(i + 1).padStart(3, '0')}`);
const TRIALS = A.trials ?? 5;
const ONLY = Array.isArray(A.only) && A.only.length ? A.only : null; // dry run, e.g. ['B:T001', 'C2:T002']
const DRY = Boolean(ONLY);

const CAP_USD = A.cap_usd ?? 40;
// Unmeasured estimates. They only reserve budget before each paid call.
// Full run estimate: 100 cells x $0.20 + 50 judge calls x $0.20 + top-ups $4 + grading $1.60 + analysis $1.50 = about $37.
const EST = {
  trial_usd: A.est_trial_usd ?? 0.03,       // one Sonnet triage conversation
  driver_usd: A.est_driver_usd ?? 0.05,     // one driver agent per cell
  grade_usd: A.est_grade_usd ?? 0.40,       // one grade agent per config batch
  judge_usd: A.est_judge_usd ?? 0.20,       // one Opus judge call per ticket (10 replies)
  analysis_usd: A.est_analysis_usd ?? 1.50, // failure analyst plus critic
};
const TOPUP_TRIALS = A.topup_trials ?? 5;
const TOPUP_CELLS_MAX = A.topup_cells_max ?? 20;
const WAVE = A.concurrency ?? 10;
const DRIVER_MODEL = A.driver_model ?? 'opus';
const JUDGE_MODEL = A.judge_model ?? 'opus';
const RUN_DIR = `spe/runs/${RR}`;
const FAIL_MAX = 200;

// Trials may not read these. A hit voids the trial and halts the run.
const FORBIDDEN = [
  'spe/evals/', 'spe/predictions/', 'spe/plans/', 'spe/runs/',
  'answers.json', 'grade.py', 'judge.md', 'prediction-log.md', 'failures.md',
];

const JUDGE_NOTE = 'The tone judge is Opus, the same model family as the Sonnet trials. No judge from another family is available in this harness, so tone scores may share blind spots with the agent.';

// ---------------- Helpers ----------------
const round3 = x => Math.round(x * 1000) / 1000;
const nums = xs => xs.filter(x => typeof x === 'number' && Number.isFinite(x));
const mean = xs => { const v = nums(xs); return v.length ? round3(v.reduce((a, b) => a + b, 0) / v.length) : null; };
const rate = (xs, f) => (xs.length ? round3(xs.filter(f).length / xs.length) : null);
const groupBy = (xs, f) => xs.reduce((m, x) => { const k = f(x); (m[k] = m[k] || []).push(x); return m; }, {});
function hash(s) {
  let h = 2166136261;
  for (const ch of s) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); }
  return h >>> 0;
}

async function inWaves(thunks) {
  const out = [];
  for (let i = 0; i < thunks.length; i += WAVE) {
    out.push(...(await parallel(thunks.slice(i, i + WAVE))));
  }
  return out;
}

// ---------------- Budget ----------------
const ledger = { spent: 0, reserved: 0, skipped: [] };
function reserve(usd, what) {
  if (ledger.spent + ledger.reserved + usd > CAP_USD) {
    ledger.skipped.push({ what, usd: round3(usd) });
    log(`SKIP ${what}: $${usd.toFixed(2)} would cross the $${CAP_USD} cap (spent $${ledger.spent.toFixed(2)}, reserved $${ledger.reserved.toFixed(2)})`);
    return false;
  }
  ledger.reserved += usd;
  return true;
}
function settle(reservedUsd, actualUsd) {
  ledger.reserved -= reservedUsd;
  ledger.spent += actualUsd;
}

// ---------------- Schemas ----------------
const TRIAL_ITEM = {
  type: 'object',
  required: ['trial', 'status'],
  properties: {
    trial: { type: 'integer' },
    status: { type: 'string', enum: ['completed', 'harness_error'] },
    error: { type: 'string' },
    category: { type: 'string' },   // no enum on purpose: a bad label must reach the grader as printed
    priority: { type: 'string' },
    reply: { type: 'string' },
    runtime_s: { type: 'number' },
    tool_calls: { type: 'integer' },
    tool_errors: { type: 'integer' },
    input_tokens: { type: 'integer' },
    output_tokens: { type: 'integer' },
    cost_usd: { type: 'number' },
    tool_trace: { type: 'array', items: { type: 'string' } },
  },
};
const DRIVER_SCHEMA = {
  type: 'object',
  required: ['commands_run', 'files_read', 'trials'],
  properties: {
    commands_run: { type: 'array', items: { type: 'string' } },
    files_read: { type: 'array', items: { type: 'string' } },
    trials: { type: 'array', items: TRIAL_ITEM },
  },
};
const GRADE_SCHEMA = {
  type: 'object',
  required: ['exit_code', 'graded', 'failures'],
  properties: {
    exit_code: { type: 'integer' },
    stderr: { type: 'string' },
    graded: { type: 'integer' },
    failures: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'category_ok', 'priority_ok'],
        properties: { id: { type: 'string' }, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' } },
      },
    },
  },
};
const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['rid', 'tone', 'pass', 'reason'],
        properties: {
          rid: { type: 'string' },
          tone: { type: 'integer', minimum: 1, maximum: 5 },
          pass: { type: 'boolean' },
          reason: { type: 'string' },
        },
      },
    },
  },
};
const ANALYSIS_SCHEMA = {
  type: 'object',
  required: ['prediction_scores', 'failures', 'proposals'],
  properties: {
    prediction_scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['metric', 'config', 'predicted', 'actual', 'verdict', 'grader_check'],
        properties: {
          metric: { type: 'string' },
          config: { type: 'string' },
          predicted: { type: 'string' },
          actual: { type: ['number', 'null'] },
          verdict: { type: 'string', enum: ['hit', 'miss', 'not_scorable'] },
          grader_check: { type: 'string' },
        },
      },
    },
    failures: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'summary', 'trials'],
        properties: { id: { type: 'string' }, summary: { type: 'string' }, trials: { type: 'array', items: { type: 'string' } } },
      },
    },
    proposals: {
      type: 'array',
      items: {
        type: 'object',
        required: ['change', 'answers'],
        properties: { change: { type: 'string' }, answers: { type: 'array', items: { type: 'string' } } },
      },
    },
  },
};
const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: { complete: { type: 'boolean' }, gaps: { type: 'array', items: { type: 'string' } } },
};

// ---------------- Cells ----------------
// Interleave by ticket so a budget skip removes the same tickets from both configs.
let cells = TICKETS.flatMap(ticket => CONFIGS.map(cfg => ({ cfg, ticket, key: `${cfg.id}:${ticket}` })));
if (ONLY) cells = cells.filter(c => ONLY.includes(c.key));

// ---------------- Trials ----------------
function driverPrompt(cfg, ticket, n, offset) {
  const cmd = `bin/triage-eval --config ${cfg.id} --ticket ${ticket} --trials ${n} --trial-offset ${offset} --json`;
  return [
    `You drive one cell of an eval for the "triage" support agent. Config ${cfg.id} is: ${cfg.desc}. Ticket ${ticket}.`,
    `Run exactly one shell command, once:`,
    `  ${cmd}`,
    `It runs ${n} independent triage conversations and prints one JSON object per trial, numbered from ${offset + 1}.`,
    `Rules:`,
    `- Do not read, open, list, search, or cat any file. Do not run any other command. Use only the command's stdout and stderr.`,
    `- Copy each trial's fields into the result exactly as printed. Do not fix, guess, or reword a label or a reply. If a label is missing, write "none".`,
    `- tool_trace is the list of tool calls the triage agent made, as printed.`,
    `- If the command exits non-zero, times out, or reports a rate limit, retry once. If it fails again, mark each affected trial "harness_error" and put the message in error.`,
    `- List every command you ran in commands_run. List every file path you touched in files_read. Leave it empty if you touched none.`,
  ].join('\n');
}

function leakHits(res) {
  const texts = [
    ...(res.commands_run || []),
    ...(res.files_read || []),
    ...(res.trials || []).flatMap(t => t.tool_trace || []),
  ];
  return texts.filter(s => FORBIDDEN.some(f => s.includes(f)));
}

function errorTrials(cfg, ticket, kind, n, offset, msg) {
  return Array.from({ length: n }, (_, i) => ({
    trial: offset + i + 1, status: 'harness_error', error: msg,
    cfg: cfg.id, ticket, kind, id: `${cfg.id}:${ticket}:${offset + i + 1}`, voided: false,
  }));
}

async function runCell(cfg, ticket, n, offset, phaseName, kind) {
  const key = `${cfg.id}:${ticket}`;
  const est = EST.driver_usd + n * EST.trial_usd;
  if (!reserve(est, `${kind} ${key} x${n}`)) return { key, kind, skipped: true, leak: [], trials: [] };
  let res;
  try {
    res = await agent(driverPrompt(cfg, ticket, n, offset), {
      label: `${kind} ${key}`, phase: phaseName, schema: DRIVER_SCHEMA, model: DRIVER_MODEL,
    });
  } catch (e) {
    settle(est, EST.driver_usd);
    log(`HARNESS ERROR ${key}: ${e.message}`);
    return { key, kind, harness_error: String(e.message), leak: [], trials: errorTrials(cfg, ticket, kind, n, offset, String(e.message)) };
  }
  const got = [...(res.trials || [])];
  if (got.length !== n) log(`WARN ${key}: expected ${n} trials, got ${got.length}. Missing trials count as harness errors.`);
  for (let i = got.length; i < n; i++) got.push({ trial: offset + i + 1, status: 'harness_error', error: 'missing from runner output' });

  const actual = EST.driver_usd + got.reduce((s, t) => s + (t.cost_usd ?? (t.status === 'completed' ? EST.trial_usd : 0)), 0);
  settle(est, actual);

  const hits = leakHits(res);
  const extra = (res.commands_run || []).filter(c => !c.trim().startsWith('bin/triage-eval'));
  if (extra.length) log(`WARN ${key}: driver ran extra commands: ${extra.join(' | ')}`);
  if (hits.length) log(`VOID ${key}: reads of hidden paths: ${hits.join(' | ')}`);

  const trials = got.map(t => ({ ...t, cfg: cfg.id, ticket, kind, id: `${cfg.id}:${ticket}:${t.trial}`, voided: hits.length > 0 }));
  return { key, kind, leak: hits, trials };
}

// ---------------- Grade (code first) ----------------
function gradePrompt(file, rows) {
  return [
    `Run the code grader for the triage eval. Do not grade any row yourself.`,
    `1. Create ${file}, and make the folder if needed. Write one JSON object per line, exactly these rows in this order:`,
    rows.map(r => JSON.stringify(r)).join('\n'),
    `2. Run: python3 spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --labels ${file} --json`,
    `3. Report the exit code, any stderr, the number of rows graded, and every row the grader marks wrong on category or priority, copied as printed.`,
    `Do not edit grade.py, answers.json, or the labels file after step 1.`,
  ].join('\n');
}

async function grade(trials, phaseName, tag) {
  const rows = trials
    .filter(t => t.status === 'completed' && !t.voided)
    .map(t => ({ id: t.id, ticket: t.ticket, category: t.category ?? 'none', priority: t.priority ?? 'none' }));
  const byId = {};
  if (!rows.length) return { byId };
  const groups = groupBy(rows, r => r.id.split(':')[0]);
  const results = await parallel(Object.entries(groups).map(([cfgId, rs]) => async () => {
    if (!reserve(EST.grade_usd, `grade ${tag} ${cfgId}`)) return { cfgId, rs, skipped: true };
    try {
      const r = await agent(gradePrompt(`${RUN_DIR}/labels-${tag}-${cfgId}.jsonl`, rs), {
        label: `grade ${tag} ${cfgId}`, phase: phaseName, schema: GRADE_SCHEMA, model: 'opus',
      });
      return { cfgId, rs, r };
    } catch (e) {
      return { cfgId, rs, error: String(e.message) };
    } finally {
      settle(EST.grade_usd, EST.grade_usd);
    }
  }));
  for (const x of results) {
    if (x.skipped) { log(`UNGRADED ${tag} ${x.cfgId}: ${x.rs.length} trials skipped on budget`); continue; }
    if (x.error) return { byId, broken: `grade run failed for ${x.cfgId}: ${x.error}` };
    if (x.r.exit_code !== 0) return { byId, broken: `grade.py exited ${x.r.exit_code} for ${x.cfgId}: ${x.r.stderr || ''}` };
    if (x.r.graded !== x.rs.length) return { byId, broken: `grade.py graded ${x.r.graded} of ${x.rs.length} rows for ${x.cfgId}` };
    const ids = new Set(x.rs.map(r => r.id));
    const unknown = x.r.failures.map(f => f.id).filter(id => !ids.has(id));
    if (unknown.length) return { byId, broken: `grade.py reported unknown ids: ${unknown.slice(0, 5).join(', ')}` };
    const fails = new Map(x.r.failures.map(f => [f.id, f]));
    for (const row of x.rs) {
      const f = fails.get(row.id);
      byId[row.id] = f ? { category_ok: f.category_ok, priority_ok: f.priority_ok } : { category_ok: true, priority_ok: true };
    }
  }
  return { byId };
}

function cellStats(trials, gradeMap) {
  const s = {};
  for (const t of trials) {
    const g = gradeMap[t.id];
    if (!g) continue;
    const k = `${t.cfg}:${t.ticket}`;
    s[k] = s[k] || { n: 0, pass: 0 };
    s[k].n += 1;
    if (g.category_ok && g.priority_ok) s[k].pass += 1;
  }
  return s;
}

// ---------------- Judge (only what code cannot check) ----------------
function judgePrompt(ticket, order) {
  return [
    `You are the tone judge for first replies to support tickets.`,
    `Read the rubric at spe/evals/graders/judge.md and follow it exactly. Do not open any other file.`,
    `Get the ticket text by running: bin/triage-eval --show-ticket ${ticket}`,
    `Score each reply below on tone only. Ignore whether the category or priority is right.`,
    `You do not know which system wrote which reply. Score each one on its own.`,
    `Return one score for every reply ID.`,
    ...order.map((t, i) => `R${i + 1}: ${JSON.stringify(t.reply)}`),
  ].join('\n');
}

async function judgeAll(trials) {
  const judgeMap = {};
  const done = trials.filter(t => t.kind === 'base' && t.status === 'completed' && !t.voided && t.reply);
  const byTicket = groupBy(done, t => t.ticket);
  const thunks = Object.entries(byTicket).map(([ticket, ts]) => async () => {
    const order = [...ts].sort((a, b) => hash(`${RR}:${a.id}`) - hash(`${RR}:${b.id}`));
    const rid = new Map(order.map((t, i) => [`R${i + 1}`, t.id]));
    const est = EST.judge_usd * Math.max(1, order.length / 10);
    if (!reserve(est, `judge ${ticket}`)) return;
    let res;
    try {
      res = await agent(judgePrompt(ticket, order), {
        label: `judge ${ticket}`, phase: 'Judge', schema: JUDGE_SCHEMA, model: JUDGE_MODEL,
      });
    } catch (e) {
      settle(est, est);
      log(`JUDGE ERROR ${ticket}: ${e.message}`);
      return;
    }
    settle(est, est);
    for (const s of res.scores || []) { const id = rid.get(s.rid); if (id) judgeMap[id] = s; }
    const missing = [...rid.keys()].filter(r => !(res.scores || []).some(s => s.rid === r));
    if (missing.length) log(`JUDGE ${ticket}: no score for ${missing.join(', ')}`);
  });
  await inWaves(thunks);
  return judgeMap;
}

// ---------------- Synthesis ----------------
function summarize(trials, gradeMap, judgeMap) {
  const by = {};
  for (const cfg of CONFIGS) {
    const mine = trials.filter(t => t.cfg === cfg.id);
    // Headline numbers use base trials only, so top-ups on hard cells do not skew them.
    const base = mine.filter(t => t.kind === 'base' && t.status === 'completed' && !t.voided && gradeMap[t.id]);
    const judged = base.filter(t => judgeMap[t.id]);
    by[cfg.id] = {
      base_trials_expected: cells.filter(c => c.cfg.id === cfg.id).length * TRIALS,
      base_trials_completed: base.length,
      harness_errors: mine.filter(t => t.status === 'harness_error').length,
      voided: mine.filter(t => t.voided).length,
      category_acc: rate(base, t => gradeMap[t.id].category_ok),
      priority_acc: rate(base, t => gradeMap[t.id].priority_ok),
      both_acc: rate(base, t => gradeMap[t.id].category_ok && gradeMap[t.id].priority_ok),
      tone_judged: judged.length,
      tone_mean: mean(judged.map(t => judgeMap[t.id].tone)),
      tone_pass: rate(judged, t => judgeMap[t.id].pass),
      runtime_s_mean: mean(base.map(t => t.runtime_s)),
      tool_calls_mean: mean(base.map(t => t.tool_calls)),
      tool_errors_mean: mean(base.map(t => t.tool_errors)),
      tokens_mean: mean(base.map(t => (t.input_tokens ?? NaN) + (t.output_tokens ?? NaN))),
      cost_usd_per_task: mean(base.map(t => t.cost_usd)),
    };
  }
  const ceiling_metrics = ['category_acc', 'priority_acc', 'both_acc', 'tone_pass']
    .filter(m => CONFIGS.every(c => by[c.id][m] === 1));
  return { by_config: by, ceiling_metrics };
}

function finish(halted, extra) {
  if (halted) log(`HALT: ${halted}`);
  return {
    round: ROUND,
    dry_run: DRY,
    halted: halted || null,
    budget: {
      cap_usd: CAP_USD,
      spent_usd: round3(ledger.spent),
      note: 'The runner measures triage cost. Driver, grader, judge, and analyst costs are estimates.',
      skipped: ledger.skipped,
    },
    judge_note: JUDGE_NOTE,
    ...extra,
  };
}

// ---------------- Main ----------------
async function main() {
  log(`${RR}: configs ${CONFIGS.map(c => c.id).join(', ')}, ${TICKETS.length} tickets, ${TRIALS} trials per cell, cap $${CAP_USD}${DRY ? `, DRY RUN on ${ONLY.join(', ')}` : ''}`);
  log(JUDGE_NOTE);
  ledger.reserved += EST.analysis_usd; // hold budget so synthesis always runs

  phase('Trials');
  const base = await inWaves(cells.map(c => () => runCell(c.cfg, c.ticket, TRIALS, 0, 'Trials', 'base')));
  const baseTrials = base.flatMap(r => r.trials);
  log(`Trials: ${baseTrials.filter(t => t.status === 'completed').length} completed, ${baseTrials.filter(t => t.status === 'harness_error').length} harness errors, ${base.filter(r => r.skipped).length} cells skipped. Spent $${ledger.spent.toFixed(2)}.`);
  const leaked = base.filter(r => r.leak.length);
  if (leaked.length) {
    return finish('leaked answer key: a trial read a hidden path', { voided_cells: leaked.map(r => ({ key: r.key, hits: r.leak })) });
  }

  phase('Grade');
  const g1 = await grade(baseTrials, 'Grade', 'base');
  if (g1.broken) return finish(`broken grader: ${g1.broken}`, {});
  const gradeMap = { ...g1.byId };

  phase('Judge');
  const judgeMap = await judgeAll(baseTrials);
  log(`Judge: ${Object.keys(judgeMap).length} replies scored. Spent $${ledger.spent.toFixed(2)}.`);

  phase('Top-up');
  const baseStats = cellStats(baseTrials, gradeMap);
  const partial = Object.entries(baseStats)
    .filter(([, s]) => s.n > 0 && s.pass > 0 && s.pass < s.n)
    .sort((a, b) => Math.abs(a[1].pass / a[1].n - 0.5) - Math.abs(b[1].pass / b[1].n - 0.5));
  const chosen = partial.slice(0, TOPUP_CELLS_MAX);
  if (partial.length > chosen.length) log(`Top-up cap: ${partial.length - chosen.length} partial cells not topped up`);
  const topups = await inWaves(chosen.map(([key]) => () => {
    const [cfgId, ticket] = key.split(':');
    const cfg = CONFIGS.find(c => c.id === cfgId);
    return runCell(cfg, ticket, TOPUP_TRIALS, TRIALS, 'Top-up', 'topup');
  }));
  const topLeaks = topups.filter(r => r.leak.length);
  if (topLeaks.length) {
    return finish('leaked answer key: a top-up trial read a hidden path', { voided_cells: topLeaks.map(r => ({ key: r.key, hits: r.leak })) });
  }
  const topTrials = topups.flatMap(r => r.trials);
  const g2 = await grade(topTrials, 'Top-up', 'topup');
  if (g2.broken) return finish(`broken grader: ${g2.broken}`, {});
  Object.assign(gradeMap, g2.byId);

  phase('Synthesis');
  const allTrials = [...baseTrials, ...topTrials];
  const summary = summarize(allTrials, gradeMap, judgeMap);
  const cellPass = Object.fromEntries(Object.entries(cellStats(allTrials, gradeMap)).map(([k, s]) => [k, `${s.pass}/${s.n}`]));
  const failing = allTrials
    .filter(t => gradeMap[t.id] && (!gradeMap[t.id].category_ok || !gradeMap[t.id].priority_ok || (judgeMap[t.id] && !judgeMap[t.id].pass)))
    .map(t => ({
      id: t.id, kind: t.kind, category: t.category, priority: t.priority, ...gradeMap[t.id],
      tone: judgeMap[t.id]?.tone ?? null, tone_reason: judgeMap[t.id]?.reason ?? null, tool_errors: t.tool_errors ?? null,
    }));
  if (failing.length > FAIL_MAX) log(`Analyst sees the first ${FAIL_MAX} of ${failing.length} failing trials`);
  const harnessErrors = allTrials.filter(t => t.status === 'harness_error').map(t => ({ id: t.id, error: t.error }));

  const analysis = await agent([
    `You are the failure analyst for round ${ROUND} of the SPE loop on the "triage" support agent. You did not write the agent or the predictions.`,
    `Read spe/predictions/${RR}.yaml and spe/plans/${RR}.md. Do not edit any file.`,
    `1. Score every prediction row for every config. A cell is a hit when the actual value is inside the predicted band. Mark a metric "not_scorable" when it is in ceiling_metrics. Name the grader check behind each row (grade.py category, grade.py priority, judge.md tone, or runner usage).`,
    `2. Group the failing trials into failures with IDs "${RR} F1", "${RR} F2", and so on. You may read spe/evals/tasks/answers.json to see the reference labels. Each failure lists its trial IDs and states the pattern.`,
    `3. If ceiling_metrics is not empty, log the saturation as a failure and propose harder tickets.`,
    `4. Propose changes for round ${NEXT_ROUND}. Each proposal names the failure IDs it answers. Change one thing per configuration.`,
    `Harness errors are not model failures. Leave them out of accuracy.`,
    `Summary: ${JSON.stringify(summary)}`,
    `Per-cell label pass counts, base plus top-up: ${JSON.stringify(cellPass)}`,
    `Failing trials: ${JSON.stringify(failing.slice(0, FAIL_MAX))}`,
    `Harness errors: ${JSON.stringify(harnessErrors)}`,
  ].join('\n'), { label: 'failure analysis', phase: 'Synthesis', schema: ANALYSIS_SCHEMA, model: 'opus' });

  const scorable = analysis.prediction_scores.filter(p => p.verdict !== 'not_scorable');
  const allHit = scorable.length > 0 && scorable.every(p => p.verdict === 'hit');

  const critic = await agent([
    `You are the completeness critic for round ${ROUND} of the triage eval. Check this report and list every gap.`,
    `1. Every planned cell has ${TRIALS} completed base trials, or a harness error, void, or budget skip explains the shortfall.`,
    `2. Harness errors are left out of accuracy and are not counted as model failures.`,
    `3. Every row in spe/predictions/${RR}.yaml has a verdict.`,
    `4. Each failure ID cites trials, and each proposal cites a failure ID.`,
    `5. Ceiling metrics are marked not scorable and logged as saturation.`,
    `6. Spend stayed under $${CAP_USD}, and skipped work is listed.`,
    `7. The judge-family caveat is stated.`,
    DRY ? `This is a dry run on ${ONLY.join(', ')}. Check only that the output shape is valid and every phase ran.` : '',
    `Report: ${JSON.stringify({ summary, analysis, budget: { spent: round3(ledger.spent), skipped: ledger.skipped }, harness_errors: harnessErrors.length, judge_note: JUDGE_NOTE })}`,
  ].join('\n'), { label: 'completeness critic', phase: 'Synthesis', schema: CRITIC_SCHEMA, model: 'opus' });

  settle(EST.analysis_usd, EST.analysis_usd);

  const budgetHalt = ledger.skipped.some(s => s.what.startsWith('base') || s.what.startsWith('judge') || s.what.startsWith('grade base'));
  return finish(budgetHalt ? 'budget cap reached before planned trials, grading, or judging finished' : null, {
    summary,
    all_predictions_hit: allHit,
    analysis,
    critic,
    cell_pass: cellPass,
    harness_errors: harnessErrors,
    topped_up_cells: chosen.map(([k]) => k),
  });
}

return await main();
